    internal sealed class LogicDecisionCriterion
    {
        public string Id { get; set; }
        public string Name { get; set; }
        public double Weight { get; set; }
        public string Direction { get; set; }
        public override string ToString() { return (Name ?? "CRITERION") + "   ·   weight " + Weight.ToString("0.000", CultureInfo.InvariantCulture) + "   ·   " + (Direction ?? "MAXIMIZE"); }
    }

    internal sealed class LogicDecisionAlternative
    {
        public string Id { get; set; }
        public string Name { get; set; }
        public Dictionary<string, double> Scores { get; set; }
        public LogicDecisionAlternative() { Scores = new Dictionary<string, double>(StringComparer.OrdinalIgnoreCase); }
        public override string ToString() { return Name ?? "ALTERNATIVE"; }
    }

    internal sealed class LogicDecisionModel
    {
        public string Id { get; set; }
        public string Name { get; set; }
        public string WorldId { get; set; }
        public string Status { get; set; }
        public string CreatedUtc { get; set; }
        public string UpdatedUtc { get; set; }
        public string Question { get; set; }
        public List<LogicDecisionCriterion> Criteria { get; set; }
        public List<LogicDecisionAlternative> Alternatives { get; set; }
        public List<string> EvidenceNodeIds { get; set; }
        public LogicDecisionModel() { Criteria = new List<LogicDecisionCriterion>(); Alternatives = new List<LogicDecisionAlternative>(); EvidenceNodeIds = new List<string>(); }
        public override string ToString() { return (Status ?? "DRAFT") + "   ·   " + (Name ?? "DECISION") + "   ·   " + Alternatives.Count.ToString(CultureInfo.InvariantCulture) + " alternatives / " + Criteria.Count.ToString(CultureInfo.InvariantCulture) + " criteria"; }
    }

