        {
            Schema = 1; Worlds = new List<LogicWorld>(); Facts = new List<LogicFact>(); Rules = new List<LogicRule>(); Theories = new List<LogicTheory>(); Hypotheses = new List<LogicHypothesis>(); SavedProofs = new List<LogicSavedProof>(); Decisions = new List<LogicDecisionModel>(); QueryHistory = new List<string>();
        }
    }

    internal sealed class LogicLedgerRecord
    {
        public int Schema { get; set; }
        public long Sequence { get; set; }
        public string Utc { get; set; }
        public string Event { get; set; }
        public string Subject { get; set; }
        public string Detail { get; set; }
        public string CorrelationId { get; set; }
        public string KernelFingerprint { get; set; }
        public string PrevHash { get; set; }
