        internal static Dictionary<string, string> ExternalTheoryTruth(DeepSystemsContext ctx, LogicTheory theory)
        {
            Dictionary<string, string> result = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase); if (ctx == null || theory == null) return result; Load(ctx); LogicWorld world = World(theory.WorldId) ?? ActualWorld(); List<LogicFact> facts = Store.Facts.Where(f => theory.FactIds.Contains(f.Id, StringComparer.OrdinalIgnoreCase)).ToList(); List<LogicRule> rules = Store.Rules.Where(r => theory.RuleIds.Contains(r.Id, StringComparer.OrdinalIgnoreCase)).ToList(); LogicEvaluation evaluation = LogicInferenceKernel.Evaluate(facts, rules, Store.Worlds, world.Id, new LogicKernelLimits()); foreach (string question in theory.Questions.Where(q => !String.IsNullOrWhiteSpace(q)).Distinct(StringComparer.OrdinalIgnoreCase).Take(MaxTheoryQuestions)) result[question] = evaluation.TruthOf(question); return result;
        }

