        private static LogicEvaluation Evaluate(LogicWorld world) { return LogicInferenceKernel.Evaluate(Store.Facts, Store.Rules, Store.Worlds, world == null ? ActualWorld().Id : world.Id, new LogicKernelLimits()); }
        private static LogicWorld ActualWorld() { LogicWorld w = Store.Worlds.FirstOrDefault(x => String.Equals(x.Kind, "ACTUAL", StringComparison.OrdinalIgnoreCase) && String.IsNullOrWhiteSpace(x.ParentWorldId)); return w ?? Store.Worlds.First(); }
        private static string CensusLine(LogicWorld world, LogicEvaluation e) { return (world.Name ?? "WORLD") + " · " + Store.Facts.Count(f => Active(f.Status)).ToString(CultureInfo.InvariantCulture) + " active facts · " + Store.Rules.Count(r => Active(r.Status)).ToString(CultureInfo.InvariantCulture) + " active rules · " + e.Derivations.Count.ToString(CultureInfo.InvariantCulture) + " signed literals · " + LogicInferenceKernel.Contradictions(e, 8192).Count.ToString(CultureInfo.InvariantCulture) + " contradiction cores · fixed point " + e.Rounds.ToString(CultureInfo.InvariantCulture) + " rounds"; }
        private static bool Active(string status) { return !String.Equals(status, "ARCHIVED", StringComparison.OrdinalIgnoreCase) && !String.Equals(status, "RETRACTED", StringComparison.OrdinalIgnoreCase) && !String.Equals(status, "DISABLED", StringComparison.OrdinalIgnoreCase); }

        private static void QueryPrompt(Window owner, DeepSystemsContext ctx, WorldIndex index, LogicWorld world)
        {
            string initial = Store.QueryHistory.FirstOrDefault() ?? "world_object(?object)"; string query = Prompt(owner, "PROOF QUERY", "Ground proposition, for example ready(track_42) or !ready(track_42)", initial); if (String.IsNullOrWhiteSpace(query)) return; LogicLiteral parsed = LogicLiteral.Parse(query); if (!parsed.IsGround) { MessageBox.Show(owner, "Proof queries must be grounded. Variables belong in rules, not tribunal questions.", "YOMI · Logic Foundry"); return; } OpenQueryResult(owner, ctx, index, world, parsed.Display);
        }

        private static void OpenQueryResult(Window owner, DeepSystemsContext ctx, WorldIndex index, LogicWorld world, string query)
        {
            LogicLiteral literal = LogicLiteral.Parse(query); LogicEvaluation e = Evaluate(world); string truth = e.TruthOf(literal.Display); Store.QueryHistory.RemoveAll(q => String.Equals(q, literal.Display, StringComparison.OrdinalIgnoreCase)); Store.QueryHistory.Insert(0, literal.Display); Store.QueryHistory = Store.QueryHistory.Take(MaxQueryHistory).ToList(); Save(ctx); AppendLedger(ctx, "QUERY", literal.Display, truth, e.KernelFingerprint); Window w = W(owner, "YOMI · PROOF TRIBUNAL · " + literal.Display, 1220, 820); DockPanel root = Shell(truth + " · " + literal.Display, "Belnap four-valued status in " + (world.Name ?? "WORLD") + " · positive and negative support remain independent · kernel " + Short(e.KernelFingerprint, 16)); WrapPanel tools = new WrapPanel { Margin = new Thickness(0, 6, 0, 8) }; tools.Children.Add(Btn("SAVE PROOF SNAPSHOT", delegate { SaveProof(ctx, world, literal.Display, e); MessageBox.Show(w, "Proof snapshot stored with kernel fingerprint.", "YOMI · Proof Vault"); })); tools.Children.Add(Btn("ABDUCE", delegate { OpenAbduction(w, ctx, index, world, literal.Display); })); tools.Children.Add(Btn("ASSERT POSITIVE", delegate { CreateFact(w, ctx, world, literal.Negated ? Opposite(literal.Display) : literal.Display, "OPERATOR_ASSERTION", 1, new string[0], ""); })); tools.Children.Add(Btn("ASSERT NEGATIVE", delegate { CreateFact(w, ctx, world, literal.Negated ? literal.Display : "!" + literal.Display, "OPERATOR_ASSERTION", 1, new string[0], ""); })); tools.Children.Add(Btn("COUNTERFACTUAL", delegate { CreateCounterfactualFromLiteral(w, ctx, index, world, literal.Display); })); DockPanel.SetDock(tools, Dock.Top); root.Children.Add(tools); Grid body = new Grid(); body.ColumnDefinitions.Add(new ColumnDefinition()); body.ColumnDefinitions.Add(new ColumnDefinition()); string positive = LogicInferenceKernel.ProofText(e, literal.Display, false); string negative = LogicInferenceKernel.ProofText(e, literal.Display, true); TextBox left = ReadOnly("SUPPORT FOR QUERY\r\n\r\n" + positive); TextBox right = ReadOnly("SUPPORT AGAINST QUERY\r\n\r\n" + negative); Grid.SetColumn(left, 0); Grid.SetColumn(right, 1); body.Children.Add(left); body.Children.Add(right); DockPanel.SetDock(body, Dock.Top); root.Children.Add(body); ListBox evidence = List(); evidence.MaxHeight = 220; evidence.ItemsSource = e.EvidenceFor(literal.Display).Where(id => index.Nodes.ContainsKey(id)).Select(id => index.Nodes[id]).ToList(); evidence.MouseDoubleClick += delegate { WorldNode n = evidence.SelectedItem as WorldNode; if (n != null) WorldKernel.ExternalOpenDossier(w, ctx, index, n.Id); }; root.Children.Add(evidence); w.Content = root; w.Show();
        }

        private static void SaveProof(DeepSystemsContext ctx, LogicWorld world, string query, LogicEvaluation e)
        {
            LogicSavedProof p = new LogicSavedProof { Id = Id("proof"), WorldId = world.Id, QueryLiteral = query, TruthStatus = e.TruthOf(query), CreatedUtc = Now(), KernelFingerprint = e.KernelFingerprint, PositiveProof = LogicInferenceKernel.ProofText(e, query, false), NegativeProof = LogicInferenceKernel.ProofText(e, query, true), EvidenceNodeIds = e.EvidenceFor(query).Take(512).ToList() }; Store.SavedProofs.Insert(0, p); TrimStore(); Save(ctx); AppendLedger(ctx, "PROOF_SAVED", p.Id, p.TruthStatus + " · " + p.QueryLiteral, p.KernelFingerprint);
        }

