        private static void CreateFactPrompt(Window owner, DeepSystemsContext ctx, LogicWorld world)
        {
            string literal = Prompt(owner, "ASSERT PROPOSITION", "Ground literal; prefix ! for explicit negation", "predicate(subject)"); if (String.IsNullOrWhiteSpace(literal)) return; LogicLiteral parsed = LogicLiteral.Parse(literal); if (!parsed.IsGround || String.IsNullOrWhiteSpace(parsed.Predicate)) { MessageBox.Show(owner, "Facts must be grounded propositions with no ?variables.", "YOMI · Proposition Vault"); return; } string epistemic = Choose(owner, "EPISTEMIC CLASS", "Classify the source of this assertion", new[] { "OPERATOR_ASSERTION", "OBSERVATION NOTE", "ORGANIZATIONAL RECORD", "HYPOTHESIS ASSUMPTION", "IMPORTED EVIDENCE" }, "OPERATOR_ASSERTION"); if (String.IsNullOrWhiteSpace(epistemic)) return; string rawWeight = Prompt(owner, "STRUCTURAL WEIGHT", "0.0 to 1.0; this ranks proof support and is not probability", "1.0"); double weight; if (!Double.TryParse(rawWeight, NumberStyles.Float, CultureInfo.InvariantCulture, out weight)) weight = 1; CreateFact(owner, ctx, world, parsed.Display, epistemic, weight, new string[0], "");
        }

        private static void CreateFact(Window owner, DeepSystemsContext ctx, LogicWorld world, string rawLiteral, string epistemicClass, double weight, IEnumerable<string> evidenceNodeIds, string sourceFingerprint)
        {
            LogicLiteral literal = LogicLiteral.Parse(rawLiteral); if (!literal.IsGround || String.IsNullOrWhiteSpace(literal.Predicate)) return; LogicFact existing = Store.Facts.FirstOrDefault(f => Active(f.Status) && String.Equals(f.WorldId, world.Id, StringComparison.OrdinalIgnoreCase) && String.Equals(LogicLiteral.Parse(f.Literal).SignedKey, literal.SignedKey, StringComparison.OrdinalIgnoreCase) && String.Equals(f.SourceFingerprint ?? "", sourceFingerprint ?? "", StringComparison.OrdinalIgnoreCase)); if (existing != null) { existing.EvidenceNodeIds = existing.EvidenceNodeIds.Concat(evidenceNodeIds ?? Enumerable.Empty<string>()).Where(x => !String.IsNullOrWhiteSpace(x)).Distinct(StringComparer.OrdinalIgnoreCase).Take(256).ToList(); existing.Weight = Math.Max(existing.Weight, Clamp01(weight)); existing.UpdatedUtc = Now(); Save(ctx); AppendLedger(ctx, "FACT_MERGED", existing.Id, literal.Display, sourceFingerprint); MessageBox.Show(owner, "Equivalent active assertion merged into the existing proposition identity.", "YOMI · Proposition Vault"); return; } LogicFact fact = new LogicFact { Id = Id("fact"), WorldId = world.Id, Literal = literal.Display, EpistemicClass = epistemicClass, Status = "ACTIVE", CreatedUtc = Now(), UpdatedUtc = Now(), Weight = Clamp01(weight), SourceFingerprint = sourceFingerprint ?? "", EvidenceNodeIds = (evidenceNodeIds ?? Enumerable.Empty<string>()).Where(x => !String.IsNullOrWhiteSpace(x)).Distinct(StringComparer.OrdinalIgnoreCase).Take(256).ToList() }; Store.Facts.Insert(0, fact); TrimStore(); Save(ctx); AppendLedger(ctx, "FACT_ASSERTED", fact.Id, fact.Literal + " · " + fact.EpistemicClass, fact.SourceFingerprint); MessageBox.Show(owner, "Proposition asserted in " + world.Name + ".", "YOMI · Proposition Vault");
        }

