            LogicWorld world = World(fact.WorldId); Window w = W(owner, "YOMI · PROPOSITION · " + fact.Literal, 1040, 700); DockPanel root = Shell((fact.Status ?? "ACTIVE") + " · " + fact.Literal, (fact.EpistemicClass ?? "ASSERTION") + " · world " + (world == null ? fact.WorldId : world.Name) + " · structural weight " + fact.Weight.ToString("0.000", CultureInfo.InvariantCulture)); WrapPanel tools = new WrapPanel { Margin = new Thickness(0, 6, 0, 8) }; tools.Children.Add(Btn(Active(fact.Status) ? "RETRACT" : "RESTORE", delegate { fact.Status = Active(fact.Status) ? "RETRACTED" : "ACTIVE"; fact.UpdatedUtc = Now(); Save(ctx); AppendLedger(ctx, "FACT_" + fact.Status, fact.Id, fact.Literal, fact.SourceFingerprint); w.Close(); })); tools.Children.Add(Btn("QUERY", delegate { OpenQueryResult(w, ctx, index, world ?? ActualWorld(), fact.Literal); })); tools.Children.Add(Btn("HADAL DESCENT", delegate { AbyssalKnowledgeEngine.DescendFromExternal(w, ctx, fact.Literal, fact, StorePath(ctx), "$facts:" + fact.Id, "LOGIC FOUNDRY › FACT"); })); DockPanel.SetDock(tools, Dock.Top); root.Children.Add(tools); ListBox evidence = List(); evidence.ItemsSource = fact.EvidenceNodeIds.Where(id => index.Nodes.ContainsKey(id)).Select(id => index.Nodes[id]).ToList(); evidence.MouseDoubleClick += delegate { WorldNode n = evidence.SelectedItem as WorldNode; if (n != null) WorldKernel.ExternalOpenDossier(w, ctx, index, n.Id); }; root.Children.Add(evidence); w.Content = root; w.Show();
        }

        private static void OpenRules(Window owner, DeepSystemsContext ctx, WorldIndex index, LogicWorld world)
        {
