        private static void CreateRulePrompt(Window owner, DeepSystemsContext ctx, LogicWorld world)
        {
            string name = Prompt(owner, "FORGE RULE", "Rule name", "Modus-derived relation"); if (String.IsNullOrWhiteSpace(name)) return; string kind = Choose(owner, "RULE SEMANTICS", "Inference behavior", new[] { "DEDUCTIVE", "DEFEASIBLE" }, "DEDUCTIVE"); if (String.IsNullOrWhiteSpace(kind)) return; string premisesRaw = PromptLarge(owner, "RULE PREMISES", "One premise per line or semicolon; variables begin with ?", "observed(?x)\r\nreliable(?x)"); if (String.IsNullOrWhiteSpace(premisesRaw)) return; List<string> premises = SplitStatements(premisesRaw); string consequentRaw = Prompt(owner, "RULE CONSEQUENT", "Consequent literal", "credible(?x)"); if (String.IsNullOrWhiteSpace(consequentRaw)) return; LogicLiteral consequent = LogicLiteral.Parse(consequentRaw); HashSet<string> bound = new HashSet<string>(premises.SelectMany(p => Variables(LogicLiteral.Parse(p))), StringComparer.OrdinalIgnoreCase); List<string> unsafeVariables = Variables(consequent).Where(v => !bound.Contains(v)).ToList(); if (unsafeVariables.Count > 0) { MessageBox.Show(owner, "Consequent contains unbound variables: " + String.Join(", ", unsafeVariables.ToArray()), "YOMI · Rule Forge"); return; } string defeatersRaw = kind == "DEFEASIBLE" ? PromptLarge(owner, "RULE DEFEATERS", "Optional blockers, one per line or semicolon", "exception(?x)") : ""; if (defeatersRaw == null) return; string priorityRaw = Prompt(owner, "RULE PRIORITY", "Integer -100 to 100; ranking only, never truth", "0"); int priority; if (!Int32.TryParse(priorityRaw, NumberStyles.Integer, CultureInfo.InvariantCulture, out priority)) priority = 0; LogicRule rule = new LogicRule { Id = Id("rule"), WorldId = world.Id, Name = name.Trim(), Kind = kind, Status = "ACTIVE", Priority = Math.Max(-100, Math.Min(100, priority)), CreatedUtc = Now(), UpdatedUtc = Now(), Premises = premises, Consequent = consequent.Display, Defeaters = SplitStatements(defeatersRaw) }; Store.Rules.Insert(0, rule); TrimStore(); Save(ctx); AppendLedger(ctx, "RULE_FORGED", rule.Id, rule.Name + " · " + rule.Kind, HashRule(rule)); MessageBox.Show(owner, "Rule forged in " + world.Name + ".", "YOMI · Rule Forge");
        }

        private static void OpenRule(Window owner, DeepSystemsContext ctx, WorldIndex index, LogicRule rule)
        {
            LogicWorld world = World(rule.WorldId); Window w = W(owner, "YOMI · RULE · " + rule.Name, 1080, 720); DockPanel root = Shell((rule.Status ?? "ACTIVE") + " · " + (rule.Kind ?? "DEDUCTIVE") + " · " + rule.Name, "Priority " + rule.Priority.ToString(CultureInfo.InvariantCulture) + " · world " + (world == null ? rule.WorldId : world.Name)); WrapPanel tools = new WrapPanel { Margin = new Thickness(0, 6, 0, 8) }; tools.Children.Add(Btn(Active(rule.Status) ? "DISABLE" : "ENABLE", delegate { rule.Status = Active(rule.Status) ? "DISABLED" : "ACTIVE"; rule.UpdatedUtc = Now(); Save(ctx); AppendLedger(ctx, "RULE_" + rule.Status, rule.Id, rule.Name, HashRule(rule)); w.Close(); })); tools.Children.Add(Btn("QUERY CONSEQUENT", delegate { LogicLiteral c = LogicLiteral.Parse(rule.Consequent); if (c.IsGround) OpenQueryResult(w, ctx, index, world ?? ActualWorld(), c.Display); else MessageBox.Show(w, "The consequent contains variables; query a grounded instance.", "YOMI · Rule Forge"); })); tools.Children.Add(Btn("HADAL DESCENT", delegate { AbyssalKnowledgeEngine.DescendFromExternal(w, ctx, rule.Name, rule, StorePath(ctx), "$rules:" + rule.Id, "LOGIC FOUNDRY › RULE"); })); DockPanel.SetDock(tools, Dock.Top); root.Children.Add(tools); StringBuilder s = new StringBuilder(); s.AppendLine("RULE ID       " + rule.Id); s.AppendLine("KIND          " + rule.Kind); s.AppendLine("WORLD         " + (world == null ? rule.WorldId : world.Name)); s.AppendLine("PRIORITY      " + rule.Priority); s.AppendLine("FINGERPRINT   " + HashRule(rule)); s.AppendLine(); s.AppendLine("PREMISES"); foreach (string p in rule.Premises) s.AppendLine("  " + p); s.AppendLine(); s.AppendLine("CONSEQUENT"); s.AppendLine("  " + rule.Consequent); s.AppendLine(); s.AppendLine("DEFEATERS"); foreach (string d in rule.Defeaters) s.AppendLine("  " + d); TextBox box = ReadOnly(s.ToString()); root.Children.Add(box); w.Content = root; w.Show();
