        private static void CreateWorldPrompt(Window owner, DeepSystemsContext ctx, LogicWorld preferredParent)
        {
            LogicWorld parent = preferredParent ?? ChooseWorld(owner, ActualWorld().Id); if (parent == null) return; string name = Prompt(owner, "CREATE MODAL WORLD", "Name for the descendant world", "Counterfactual " + DateTime.Now.ToString("yyyy-MM-dd HHmm", CultureInfo.InvariantCulture)); if (String.IsNullOrWhiteSpace(name)) return; string kind = Choose(owner, "WORLD KIND", "Modal semantics", new[] { "HYPOTHETICAL", "COUNTERFACTUAL", "SCENARIO", "POSSIBLE" }, "HYPOTHETICAL"); if (String.IsNullOrWhiteSpace(kind)) return; string charter = PromptLarge(owner, "WORLD CHARTER", "State the intervention, assumptions and intended scope", "Explore consequences without mutating the parent world."); if (charter == null) return; LogicWorld world = new LogicWorld { Id = Id("world"), ParentWorldId = parent.Id, Name = Short(name.Trim(), 160), Kind = kind, Status = "ACTIVE", CreatedUtc = Now(), UpdatedUtc = Now(), Charter = Short(charter, MaxLongText) }; Store.Worlds.Add(world); TrimStore(); Save(ctx); AppendLedger(ctx, "WORLD_CREATED", world.Id, world.Name + " · parent " + parent.Id, HashText(world.Charter)); OpenWorld(owner, ctx, WorldKernel.ExternalIndex(ctx, false), world);
        }

        private static void CreateCounterfactualFromLiteral(Window owner, DeepSystemsContext ctx, WorldIndex index, LogicWorld parent, string literal)
        {
            LogicLiteral q = LogicLiteral.Parse(literal); LogicWorld world = new LogicWorld { Id = Id("world"), ParentWorldId = parent.Id, Name = "Counterfactual · " + Opposite(q.Display), Kind = "COUNTERFACTUAL", Status = "ACTIVE", CreatedUtc = Now(), UpdatedUtc = Now(), Charter = "Intervention: suppose " + Opposite(q.Display) + ". The parent remains unchanged." }; Store.Worlds.Add(world); LogicFact intervention = new LogicFact { Id = Id("fact"), WorldId = world.Id, Literal = Opposite(q.Display), EpistemicClass = "COUNTERFACTUAL INTERVENTION", Status = "ACTIVE", CreatedUtc = Now(), UpdatedUtc = Now(), Weight = 1, SourceFingerprint = HashText(world.Id + "|" + q.SignedKey) }; Store.Facts.Insert(0, intervention); foreach (LogicFact f in VisibleFacts(parent).Where(f => String.Equals(LogicLiteral.Parse(f.Literal).SignedKey, q.SignedKey, StringComparison.OrdinalIgnoreCase))) world.ExcludedFactIds.Add(f.Id); TrimStore(); Save(ctx); AppendLedger(ctx, "COUNTERFACTUAL_CREATED", world.Id, world.Charter, intervention.SourceFingerprint); OpenWorld(owner, ctx, index, world);
        }

