        private static void ExcludeFactPrompt(Window owner, DeepSystemsContext ctx, LogicWorld world)
        {
            List<LogicFact> inherited = VisibleFacts(world).Where(f => !String.Equals(f.WorldId, world.Id, StringComparison.OrdinalIgnoreCase) && !world.ExcludedFactIds.Contains(f.Id, StringComparer.OrdinalIgnoreCase)).OrderBy(f => f.Literal).ToList(); LogicFact selected = ChooseObject(owner, "EXCLUDE INHERITED FACT", "Select an inherited assertion to mask only in this world", inherited.Cast<object>().ToList()) as LogicFact; if (selected == null) return; world.ExcludedFactIds.Add(selected.Id); world.ExcludedFactIds = world.ExcludedFactIds.Distinct(StringComparer.OrdinalIgnoreCase).Take(MaxFacts).ToList(); world.UpdatedUtc = Now(); Save(ctx); AppendLedger(ctx, "WORLD_FACT_EXCLUDED", world.Id, selected.Id + " · " + selected.Literal, ""); MessageBox.Show(owner, "Inherited assertion excluded in this world only.", "YOMI · Modal World Forge");
        }

