        private static void CreateDecisionPrompt(Window owner, DeepSystemsContext ctx, LogicWorld world)
        {
            string name = Prompt(owner, "DECISION MODEL", "Model name", "Strategic choice"); if (String.IsNullOrWhiteSpace(name)) return; string question = PromptLarge(owner, "DECISION QUESTION", "What choice is this model interrogating?", "Which alternative best satisfies the declared criteria?"); if (question == null) return; string criteriaRaw = PromptLarge(owner, "CRITERIA", "One per line: name | weight | MAXIMIZE or MINIMIZE", "Expected value | 0.40 | MAXIMIZE\r\nReversibility | 0.30 | MAXIMIZE\r\nExecution risk | 0.30 | MINIMIZE"); if (String.IsNullOrWhiteSpace(criteriaRaw)) return; List<LogicDecisionCriterion> criteria = ParseCriteria(criteriaRaw); if (criteria.Count == 0) { MessageBox.Show(owner, "No valid criteria. Use name | weight | direction.", "YOMI · Decision Lab"); return; } string alternativesRaw = PromptLarge(owner, "ALTERNATIVES", "One alternative name per line", "Alternative Alpha\r\nAlternative Beta\r\nAlternative Gamma"); if (String.IsNullOrWhiteSpace(alternativesRaw)) return; List<string> names = SplitStatements(alternativesRaw).Distinct(StringComparer.OrdinalIgnoreCase).Take(32).ToList(); if (names.Count < 2) { MessageBox.Show(owner, "A decision comparison requires at least two alternatives.", "YOMI · Decision Lab"); return; } LogicDecisionModel model = new LogicDecisionModel { Id = Id("decision"), Name = Short(name, 240), WorldId = world.Id, Status = "DRAFT", CreatedUtc = Now(), UpdatedUtc = Now(), Question = Short(question, MaxLongText), Criteria = criteria }; foreach (string alternativeName in names) { LogicDecisionAlternative alternative = new LogicDecisionAlternative { Id = Id("alt"), Name = Short(alternativeName, 240) }; foreach (LogicDecisionCriterion criterion in criteria) { string raw = Prompt(owner, "SCORE · " + alternative.Name, criterion.Name + " · enter an estimate from 0 to 100", "50"); double score; if (!Double.TryParse(raw, NumberStyles.Float, CultureInfo.InvariantCulture, out score)) score = 50; alternative.Scores[criterion.Id] = Math.Max(0, Math.Min(100, score)); } model.Alternatives.Add(alternative); } Store.Decisions.Insert(0, model); TrimStore(); Save(ctx); AppendLedger(ctx, "DECISION_CREATED", model.Id, model.Name + " · " + model.Alternatives.Count + " alternatives", DecisionFingerprint(model)); OpenDecision(owner, ctx, WorldKernel.ExternalIndex(ctx, false), model);
        }

        private static void OpenDecision(Window owner, DeepSystemsContext ctx, WorldIndex index, LogicDecisionModel model)
        {
            List<LogicDecisionResultRow> results = AnalyzeDecision(model); Window w = W(owner, "YOMI · DECISION · " + model.Name, 1220, 820); DockPanel root = Shell((model.Status ?? "DRAFT") + " · " + model.Name, (model.Question ?? "") + "\r\nScores are value-laden estimates, never proposition truth · fingerprint " + Short(DecisionFingerprint(model), 20)); WrapPanel tools = new WrapPanel { Margin = new Thickness(0, 6, 0, 8) }; tools.Children.Add(Btn("EDIT SCORE", delegate { EditDecisionScore(w, ctx, model); })); tools.Children.Add(Btn("SET STATUS", delegate { string status = Choose(w, "DECISION STATUS", "Lifecycle", new[] { "DRAFT", "UNDER REVIEW", "ADOPTED", "REJECTED", "SUPERSEDED", "ARCHIVED" }, model.Status); if (!String.IsNullOrWhiteSpace(status)) { model.Status = status; model.UpdatedUtc = Now(); Save(ctx); AppendLedger(ctx, "DECISION_STATUS", model.Id, status, DecisionFingerprint(model)); } })); tools.Children.Add(Btn("HADAL DESCENT", delegate { AbyssalKnowledgeEngine.DescendFromExternal(w, ctx, model.Name, model, StorePath(ctx), "$decisions:" + model.Id, "LOGIC FOUNDRY › DECISION"); })); DockPanel.SetDock(tools, Dock.Top); root.Children.Add(tools); Grid grid = new Grid(); grid.ColumnDefinitions.Add(new ColumnDefinition()); grid.ColumnDefinitions.Add(new ColumnDefinition()); ListBox ranking = List(); ranking.ItemsSource = results; StringBuilder dossier = new StringBuilder(); dossier.AppendLine("CRITERIA"); foreach (LogicDecisionCriterion c in NormalizeCriteria(model.Criteria)) dossier.AppendLine("  " + c.Name + " · normalized weight " + c.Weight.ToString("0.000", CultureInfo.InvariantCulture) + " · " + c.Direction); dossier.AppendLine(); dossier.AppendLine("ANALYTIC SEMANTICS"); dossier.AppendLine("  Weighted utility: normalized additive value under declared weights."); dossier.AppendLine("  Pareto: no rival is at least as good on every criterion and better on one."); dossier.AppendLine("  Minimax regret: lowest worst criterion-level opportunity loss."); dossier.AppendLine("  Robustness: share of deterministic weight perturbations retaining rank one."); TextBox explanation = ReadOnly(dossier.ToString()); Grid.SetColumn(ranking, 0); Grid.SetColumn(explanation, 1); grid.Children.Add(ranking); grid.Children.Add(explanation); root.Children.Add(grid); w.Content = root; w.Show();
        }

        private static void EditDecisionScore(Window owner, DeepSystemsContext ctx, LogicDecisionModel model)
        {
            LogicDecisionAlternative alternative = ChooseObject(owner, "EDIT ALTERNATIVE", "Select alternative", model.Alternatives.Cast<object>().ToList()) as LogicDecisionAlternative; if (alternative == null) return; LogicDecisionCriterion criterion = ChooseObject(owner, "EDIT CRITERION", "Select criterion", model.Criteria.Cast<object>().ToList()) as LogicDecisionCriterion; if (criterion == null) return; double current; if (!alternative.Scores.TryGetValue(criterion.Id, out current)) current = 50; string raw = Prompt(owner, "EDIT SCORE", alternative.Name + " · " + criterion.Name + " · 0 to 100", current.ToString("0.###", CultureInfo.InvariantCulture)); double score; if (!Double.TryParse(raw, NumberStyles.Float, CultureInfo.InvariantCulture, out score)) return; alternative.Scores[criterion.Id] = Math.Max(0, Math.Min(100, score)); model.UpdatedUtc = Now(); Save(ctx); AppendLedger(ctx, "DECISION_SCORE_EDITED", model.Id, alternative.Id + " · " + criterion.Id + " · " + score.ToString("0.###", CultureInfo.InvariantCulture), DecisionFingerprint(model));
        }

        private static List<LogicDecisionCriterion> ParseCriteria(string raw)
        {
            List<LogicDecisionCriterion> rows = new List<LogicDecisionCriterion>(); foreach (string line in SplitStatements(raw).Take(32)) { string[] parts = line.Split('|'); if (parts.Length == 0 || String.IsNullOrWhiteSpace(parts[0])) continue; double weight = 1; if (parts.Length > 1) Double.TryParse(parts[1].Trim(), NumberStyles.Float, CultureInfo.InvariantCulture, out weight); string direction = parts.Length > 2 && parts[2].Trim().StartsWith("MIN", StringComparison.OrdinalIgnoreCase) ? "MINIMIZE" : "MAXIMIZE"; rows.Add(new LogicDecisionCriterion { Id = Id("criterion"), Name = Short(parts[0].Trim(), 180), Weight = Math.Max(0, weight), Direction = direction }); } return NormalizeCriteria(rows);
        }

        private static List<LogicDecisionCriterion> NormalizeCriteria(IEnumerable<LogicDecisionCriterion> source)
        {
            List<LogicDecisionCriterion> rows = (source ?? Enumerable.Empty<LogicDecisionCriterion>()).ToList(); double total = rows.Sum(c => Math.Max(0, c.Weight)); if (total <= 0 && rows.Count > 0) { foreach (LogicDecisionCriterion c in rows) c.Weight = 1.0 / rows.Count; } else if (total > 0) foreach (LogicDecisionCriterion c in rows) c.Weight = Math.Max(0, c.Weight) / total; return rows;
        }

        private static List<LogicDecisionResultRow> AnalyzeDecision(LogicDecisionModel model)
        {
            if (model == null || model.Alternatives == null || model.Alternatives.Count == 0) return new List<LogicDecisionResultRow>(); List<LogicDecisionCriterion> criteria = NormalizeCriteria(model.Criteria); Dictionary<string, double> utility = new Dictionary<string, double>(StringComparer.OrdinalIgnoreCase); Dictionary<string, double> regret = new Dictionary<string, double>(StringComparer.OrdinalIgnoreCase); Dictionary<string, int> robustWins = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase); foreach (LogicDecisionAlternative a in model.Alternatives) { utility[a.Id] = Utility(a, criteria, null); regret[a.Id] = MaxRegret(a, model.Alternatives, criteria); robustWins[a.Id] = 0; } int simulations = Math.Max(1, criteria.Count * 8); for (int i = 0; i < simulations; i++) { Dictionary<string, double> perturbed = new Dictionary<string, double>(StringComparer.OrdinalIgnoreCase); for (int c = 0; c < criteria.Count; c++) { double wave = (((i + 1) * (c + 3) * 37) % 101) / 100.0; perturbed[criteria[c].Id] = Math.Max(0.001, criteria[c].Weight * (0.75 + 0.5 * wave)); } double sum = perturbed.Values.Sum(); foreach (string key in perturbed.Keys.ToList()) perturbed[key] /= sum; double best = model.Alternatives.Max(a => Utility(a, criteria, perturbed)); foreach (LogicDecisionAlternative a in model.Alternatives.Where(a => Math.Abs(Utility(a, criteria, perturbed) - best) < 0.0000001)) robustWins[a.Id]++; } List<LogicDecisionResultRow> rows = new List<LogicDecisionResultRow>(); foreach (LogicDecisionAlternative a in model.Alternatives) rows.Add(new LogicDecisionResultRow { Alternative = a.Name, Utility = utility[a.Id], Pareto = !model.Alternatives.Any(b => !Object.ReferenceEquals(a, b) && Dominates(b, a, criteria)), MaxRegret = regret[a.Id], Robustness = robustWins[a.Id] / (double)simulations }); int rank = 1; foreach (LogicDecisionResultRow row in rows.OrderByDescending(x => x.Utility).ThenBy(x => x.MaxRegret).ThenByDescending(x => x.Robustness)) row.Rank = rank++; return rows.OrderBy(x => x.Rank).ToList();
        }

        private static double Utility(LogicDecisionAlternative alternative, IEnumerable<LogicDecisionCriterion> criteria, Dictionary<string, double> weightOverride)
        {
            double total = 0; foreach (LogicDecisionCriterion c in criteria) { double score; if (!alternative.Scores.TryGetValue(c.Id, out score)) score = 0; double value = String.Equals(c.Direction, "MINIMIZE", StringComparison.OrdinalIgnoreCase) ? 1 - Clamp01(score / 100.0) : Clamp01(score / 100.0); double weight; if (weightOverride == null || !weightOverride.TryGetValue(c.Id, out weight)) weight = c.Weight; total += weight * value; } return total;
        }

        private static bool Dominates(LogicDecisionAlternative a, LogicDecisionAlternative b, IEnumerable<LogicDecisionCriterion> criteria)
        {
            bool strict = false; foreach (LogicDecisionCriterion c in criteria) { double av, bv; if (!a.Scores.TryGetValue(c.Id, out av)) av = 0; if (!b.Scores.TryGetValue(c.Id, out bv)) bv = 0; if (String.Equals(c.Direction, "MINIMIZE", StringComparison.OrdinalIgnoreCase)) { if (av > bv) return false; if (av < bv) strict = true; } else { if (av < bv) return false; if (av > bv) strict = true; } } return strict;
        }

        private static double MaxRegret(LogicDecisionAlternative alternative, IEnumerable<LogicDecisionAlternative> alternatives, IEnumerable<LogicDecisionCriterion> criteria)
        {
            double max = 0; foreach (LogicDecisionCriterion c in criteria) { double score; if (!alternative.Scores.TryGetValue(c.Id, out score)) score = 0; double best = String.Equals(c.Direction, "MINIMIZE", StringComparison.OrdinalIgnoreCase) ? alternatives.Min(a => ScoreOf(a, c.Id)) : alternatives.Max(a => ScoreOf(a, c.Id)); double delta = Math.Abs(best - score) / 100.0; max = Math.Max(max, delta); } return max;
        }

        private static double ScoreOf(LogicDecisionAlternative alternative, string criterionId) { double score; return alternative.Scores.TryGetValue(criterionId, out score) ? score : 0; }
        private static string DecisionFingerprint(LogicDecisionModel model) { return HashText(Json.Serialize(model)); }

