        private static void OpenModalSpectrum(Window owner, DeepSystemsContext ctx, WorldIndex index, string query)
        {
            List<LogicModalTruthRow> rows = new List<LogicModalTruthRow>(); foreach (LogicWorld world in Store.Worlds.Where(q => Active(q.Status)).OrderBy(q => WorldDepth(q)).ThenBy(q => q.Name)) { LogicEvaluation e = Evaluate(world); rows.Add(new LogicModalTruthRow { World = world, Truth = e.TruthOf(query), KernelFingerprint = e.KernelFingerprint, Contradictions = LogicInferenceKernel.Contradictions(e, 8192).Count }); } int support = rows.Count(r => r.Truth == "TRUE_ONLY" || r.Truth == "BOTH"); int refute = rows.Count(r => r.Truth == "FALSE_ONLY" || r.Truth == "BOTH"); int both = rows.Count(r => r.Truth == "BOTH"); string modal = rows.Count == 0 ? "NO ACTIVE WORLDS" : support == rows.Count ? (both > 0 ? "SUPPORTED IN ALL · INCONSISTENT SOMEWHERE" : "NECESSARY RELATIVE TO ACTIVE WORLDS") : support > 0 ? "POSSIBLE RELATIVE TO ACTIVE WORLDS" : refute == rows.Count ? "REFUTED IN ALL ACTIVE WORLDS" : "UNSUPPORTED IN ACTIVE WORLDS"; Window w = W(owner, "YOMI · MODAL SPECTRUM · " + query, 1200, 800); DockPanel root = Shell(modal + " · " + query, support.ToString(CultureInfo.InvariantCulture) + " supporting worlds · " + refute.ToString(CultureInfo.InvariantCulture) + " refuting worlds · " + both.ToString(CultureInfo.InvariantCulture) + " inconsistent worlds · modality is relative to the bounded active world set"); ListBox list = List(); list.ItemsSource = rows; list.MouseDoubleClick += delegate { LogicModalTruthRow row = list.SelectedItem as LogicModalTruthRow; if (row != null) OpenQueryResult(w, ctx, index, row.World, query); }; root.Children.Add(list); w.Content = root; w.Show(); AppendLedger(ctx, "MODAL_SPECTRUM", query, modal + " · worlds " + rows.Count, HashText(String.Join("|", rows.Select(r => r.World.Id + ":" + r.Truth).ToArray())));
        }

        private static void OpenRuleDependencies(Window owner, DeepSystemsContext ctx, WorldIndex index, LogicWorld world)
        {
            List<LogicRule> rules = VisibleRules(world).Where(r => Active(r.Status)).ToList(); Dictionary<string, HashSet<string>> graph = new Dictionary<string, HashSet<string>>(StringComparer.OrdinalIgnoreCase); foreach (LogicRule rule in rules) { LogicLiteral consequent = LogicLiteral.Parse(rule.Consequent); EnsureVertex(graph, consequent.Predicate); foreach (LogicLiteral premise in rule.Premises.Select(LogicLiteral.Parse)) { EnsureVertex(graph, premise.Predicate); if (!String.IsNullOrWhiteSpace(premise.Predicate) && !String.IsNullOrWhiteSpace(consequent.Predicate)) graph[premise.Predicate].Add(consequent.Predicate); } } List<List<string>> components = StronglyConnectedComponents(graph); List<LogicRuleComponentRow> rows = new List<LogicRuleComponentRow>(); foreach (List<string> component in components) { HashSet<string> members = new HashSet<string>(component, StringComparer.OrdinalIgnoreCase); List<LogicRule> participating = rules.Where(r => members.Contains(LogicLiteral.Parse(r.Consequent).Predicate) || r.Premises.Select(LogicLiteral.Parse).Any(p => members.Contains(p.Predicate))).ToList(); bool selfLoop = component.Count == 1 && graph.ContainsKey(component[0]) && graph[component[0]].Contains(component[0]); rows.Add(new LogicRuleComponentRow { Predicates = component.OrderBy(x => x).ToList(), Rules = participating, Recursive = component.Count > 1 || selfLoop, InternalEdges = graph.Where(kv => members.Contains(kv.Key)).Sum(kv => kv.Value.Count(members.Contains)) }); } Window w = W(owner, "YOMI · RULE DEPENDENCY OBSERVATORY", 1200, 800); DockPanel root = Shell("PREDICATE DEPENDENCY COMPONENTS · " + world.Name, graph.Count.ToString(CultureInfo.InvariantCulture) + " predicates · " + graph.Sum(kv => kv.Value.Count).ToString(CultureInfo.InvariantCulture) + " directed dependencies · " + rows.Count(r => r.Recursive).ToString(CultureInfo.InvariantCulture) + " recursive components · recursion is structural, not automatically erroneous"); ListBox list = List(); list.ItemsSource = rows.OrderByDescending(r => r.Recursive).ThenByDescending(r => r.Predicates.Count).ThenBy(r => r.Predicates.FirstOrDefault()).ToList(); list.MouseDoubleClick += delegate { LogicRuleComponentRow row = list.SelectedItem as LogicRuleComponentRow; if (row != null) OpenRuleComponent(w, ctx, index, row); }; root.Children.Add(list); w.Content = root; w.Show();
        }

        private static void OpenRuleComponent(Window owner, DeepSystemsContext ctx, WorldIndex index, LogicRuleComponentRow component)
        {
            Window w = W(owner, "YOMI · RULE COMPONENT", 1120, 760); DockPanel root = Shell((component.Recursive ? "RECURSIVE" : "ACYCLIC") + " PREDICATE COMPONENT", String.Join(", ", component.Predicates.ToArray()) + " · internal edges " + component.InternalEdges.ToString(CultureInfo.InvariantCulture)); ListBox list = List(); list.ItemsSource = component.Rules.OrderByDescending(r => r.Priority).ThenBy(r => r.Name).ToList(); list.MouseDoubleClick += delegate { LogicRule rule = list.SelectedItem as LogicRule; if (rule != null) OpenRule(w, ctx, index, rule); }; root.Children.Add(list); w.Content = root; w.Show();
        }

        private static void EnsureVertex(Dictionary<string, HashSet<string>> graph, string predicate) { if (String.IsNullOrWhiteSpace(predicate)) return; if (!graph.ContainsKey(predicate)) graph[predicate] = new HashSet<string>(StringComparer.OrdinalIgnoreCase); }
        private static List<List<string>> StronglyConnectedComponents(Dictionary<string, HashSet<string>> graph)
        {
            List<List<string>> result = new List<List<string>>(); Dictionary<string, int> index = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase); Dictionary<string, int> low = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase); Stack<string> stack = new Stack<string>(); HashSet<string> onStack = new HashSet<string>(StringComparer.OrdinalIgnoreCase); int cursor = 0; Action<string> visit = null; visit = delegate(string vertex) { index[vertex] = cursor; low[vertex] = cursor; cursor++; stack.Push(vertex); onStack.Add(vertex); foreach (string next in graph[vertex]) { if (!index.ContainsKey(next)) { visit(next); low[vertex] = Math.Min(low[vertex], low[next]); } else if (onStack.Contains(next)) low[vertex] = Math.Min(low[vertex], index[next]); } if (low[vertex] != index[vertex]) return; List<string> component = new List<string>(); string member; do { member = stack.Pop(); onStack.Remove(member); component.Add(member); } while (!String.Equals(member, vertex, StringComparison.OrdinalIgnoreCase)); result.Add(component); }; foreach (string vertex in graph.Keys.OrderBy(x => x)) if (!index.ContainsKey(vertex)) visit(vertex); return result;
        }

        private static void OpenAudit(Window owner, DeepSystemsContext ctx, WorldIndex index)
        {
            List<LogicAuditFinding> findings = BuildAuditFindings(ctx, index); int failures = findings.Count(f => f.Severity == "FAIL"), warnings = findings.Count(f => f.Severity == "WARN"); Window w = W(owner, "YOMI · FOUNDRY AUDIT CHAMBER", 1220, 820); DockPanel root = Shell("READ-ONLY EPISTEMIC INTEGRITY AUDIT", failures.ToString(CultureInfo.InvariantCulture) + " failures · " + warnings.ToString(CultureInfo.InvariantCulture) + " warnings · " + findings.Count(f => f.Severity == "INFO").ToString(CultureInfo.InvariantCulture) + " information findings · inspection never grants repair authority"); ListBox list = List(); list.ItemsSource = findings.OrderBy(f => f.Severity == "FAIL" ? 0 : f.Severity == "WARN" ? 1 : 2).ThenBy(f => f.Code).ThenBy(f => f.SubjectId).ToList(); list.MouseDoubleClick += delegate { LogicAuditFinding finding = list.SelectedItem as LogicAuditFinding; if (finding == null) return; if (!String.IsNullOrWhiteSpace(finding.NodeId) && index.Nodes.ContainsKey(finding.NodeId)) WorldKernel.ExternalOpenDossier(w, ctx, index, finding.NodeId); else DeepSystems.OpenExternalValue(w, ctx, finding.Code + " · " + finding.SubjectId, finding, "LOGIC FOUNDRY › AUDIT"); }; root.Children.Add(list); w.Content = root; w.Show(); AppendLedger(ctx, "FOUNDRY_AUDIT", "store", failures + " failures · " + warnings + " warnings", HashText(String.Join("|", findings.Select(f => f.Severity + ":" + f.Code + ":" + f.SubjectId).ToArray())));
        }

        private static List<LogicAuditFinding> BuildAuditFindings(DeepSystemsContext ctx, WorldIndex index)
        {
            List<LogicAuditFinding> rows = new List<LogicAuditFinding>(); List<string> identities = new List<string>(); identities.AddRange(Store.Worlds.Select(x => x.Id)); identities.AddRange(Store.Facts.Select(x => x.Id)); identities.AddRange(Store.Rules.Select(x => x.Id)); identities.AddRange(Store.Theories.Select(x => x.Id)); identities.AddRange(Store.Hypotheses.Select(x => x.Id)); identities.AddRange(Store.SavedProofs.Select(x => x.Id)); identities.AddRange(Store.Decisions.Select(x => x.Id)); foreach (IGrouping<string, string> duplicate in identities.Where(x => !String.IsNullOrWhiteSpace(x)).GroupBy(x => x, StringComparer.OrdinalIgnoreCase).Where(g => g.Count() > 1)) Audit(rows, "FAIL", "DUPLICATE_ID", duplicate.Key, duplicate.Count() + " objects share one identity", null);
            foreach (LogicWorld world in Store.Worlds) { if (!String.IsNullOrWhiteSpace(world.ParentWorldId) && World(world.ParentWorldId) == null) Audit(rows, "FAIL", "MISSING_WORLD_PARENT", world.Id, world.ParentWorldId, null); List<LogicWorld> ancestry = WorldAncestry(world); if (ancestry.Count >= 64) Audit(rows, "WARN", "WORLD_DEPTH_BOUND", world.Id, "Ancestry reached the 64-world traversal bound", null); if (HasWorldCycle(world)) Audit(rows, "FAIL", "WORLD_CYCLE", world.Id, "World parent lineage repeats an identity", null); foreach (string excluded in world.ExcludedFactIds.Where(id => !Store.Facts.Any(f => String.Equals(f.Id, id, StringComparison.OrdinalIgnoreCase)))) Audit(rows, "WARN", "ORPHAN_FACT_EXCLUSION", world.Id, excluded, null); }
            foreach (LogicFact fact in Store.Facts) { LogicLiteral literal = LogicLiteral.Parse(fact.Literal); if (String.IsNullOrWhiteSpace(literal.Predicate) || !literal.IsGround) Audit(rows, "FAIL", "MALFORMED_FACT_LITERAL", fact.Id, fact.Literal, null); if (World(fact.WorldId) == null) Audit(rows, "FAIL", "ORPHAN_FACT_WORLD", fact.Id, fact.WorldId, null); if (fact.Weight < 0 || fact.Weight > 1) Audit(rows, "WARN", "FACT_WEIGHT_RANGE", fact.Id, fact.Weight.ToString(CultureInfo.InvariantCulture), null); foreach (string nodeId in fact.EvidenceNodeIds.Where(id => !index.Nodes.ContainsKey(id))) Audit(rows, "INFO", "FACT_EVIDENCE_ABSENT", fact.Id, nodeId, nodeId); }
            foreach (LogicRule rule in Store.Rules) { if (World(rule.WorldId) == null) Audit(rows, "FAIL", "ORPHAN_RULE_WORLD", rule.Id, rule.WorldId, null); LogicLiteral consequent = LogicLiteral.Parse(rule.Consequent); if (String.IsNullOrWhiteSpace(consequent.Predicate)) Audit(rows, "FAIL", "MALFORMED_CONSEQUENT", rule.Id, rule.Consequent, null); HashSet<string> bound = new HashSet<string>(rule.Premises.SelectMany(p => Variables(LogicLiteral.Parse(p))), StringComparer.OrdinalIgnoreCase); foreach (string variable in Variables(consequent).Where(v => !bound.Contains(v))) Audit(rows, "FAIL", "UNSAFE_CONSEQUENT_VARIABLE", rule.Id, variable, null); foreach (string premise in rule.Premises.Where(p => String.IsNullOrWhiteSpace(LogicLiteral.Parse(p).Predicate))) Audit(rows, "FAIL", "MALFORMED_PREMISE", rule.Id, premise, null); foreach (string defeater in rule.Defeaters.Where(d => String.IsNullOrWhiteSpace(LogicLiteral.Parse(d).Predicate))) Audit(rows, "WARN", "MALFORMED_DEFEATER", rule.Id, defeater, null); }
            foreach (LogicTheory theory in Store.Theories) { if (World(theory.WorldId) == null) Audit(rows, "FAIL", "ORPHAN_THEORY_WORLD", theory.Id, theory.WorldId, null); foreach (string id in theory.FactIds.Where(id => !Store.Facts.Any(f => String.Equals(f.Id, id, StringComparison.OrdinalIgnoreCase)))) Audit(rows, "INFO", "THEORY_FACT_UNAVAILABLE", theory.Id, id, null); foreach (string id in theory.RuleIds.Where(id => !Store.Rules.Any(r => String.Equals(r.Id, id, StringComparison.OrdinalIgnoreCase)))) Audit(rows, "INFO", "THEORY_RULE_UNAVAILABLE", theory.Id, id, null); foreach (string q in theory.Questions.Where(q => !LogicLiteral.Parse(q).IsGround)) Audit(rows, "WARN", "UNGROUNDED_THEORY_QUERY", theory.Id, q, null); }
            foreach (LogicHypothesis hypothesis in Store.Hypotheses) { if (World(hypothesis.WorldId) == null) Audit(rows, "FAIL", "ORPHAN_HYPOTHESIS_WORLD", hypothesis.Id, hypothesis.WorldId, null); foreach (string assumption in hypothesis.Assumptions.Where(a => !LogicLiteral.Parse(a).IsGround)) Audit(rows, "FAIL", "UNGROUNDED_ASSUMPTION", hypothesis.Id, assumption, null); foreach (string nodeId in hypothesis.EvidenceNodeIds.Where(id => !index.Nodes.ContainsKey(id))) Audit(rows, "INFO", "HYPOTHESIS_EVIDENCE_ABSENT", hypothesis.Id, nodeId, nodeId); }
            foreach (LogicSavedProof proof in Store.SavedProofs) { if (World(proof.WorldId) == null) Audit(rows, "WARN", "ORPHAN_PROOF_WORLD", proof.Id, proof.WorldId, null); if (String.IsNullOrWhiteSpace(proof.KernelFingerprint)) Audit(rows, "WARN", "PROOF_WITHOUT_KERNEL", proof.Id, proof.QueryLiteral, null); }
            foreach (LogicDecisionModel decision in Store.Decisions) { if (World(decision.WorldId) == null) Audit(rows, "WARN", "ORPHAN_DECISION_WORLD", decision.Id, decision.WorldId, null); if (decision.Alternatives.Count < 2) Audit(rows, "WARN", "DECISION_CARDINALITY", decision.Id, "Fewer than two alternatives", null); if (decision.Criteria.Count == 0) Audit(rows, "WARN", "DECISION_NO_CRITERIA", decision.Id, "No declared criteria", null); foreach (LogicDecisionAlternative alternative in decision.Alternatives) foreach (LogicDecisionCriterion criterion in decision.Criteria) if (!alternative.Scores.ContainsKey(criterion.Id)) Audit(rows, "WARN", "DECISION_SCORE_MISSING", decision.Id, alternative.Id + " / " + criterion.Id, null); }
            AuditBound(rows, "WORLDS", Store.Worlds.Count, MaxWorlds); AuditBound(rows, "FACTS", Store.Facts.Count, MaxFacts); AuditBound(rows, "RULES", Store.Rules.Count, MaxRules); AuditBound(rows, "THEORIES", Store.Theories.Count, MaxTheories); AuditBound(rows, "HYPOTHESES", Store.Hypotheses.Count, MaxHypotheses); AuditBound(rows, "PROOFS", Store.SavedProofs.Count, MaxSavedProofs); AuditBound(rows, "DECISIONS", Store.Decisions.Count, MaxDecisions); foreach (LogicRule rule in Store.Rules) { AuditBound(rows, "RULE_PREMISES:" + rule.Id, rule.Premises.Count, MaxRulePremises); AuditBound(rows, "RULE_DEFEATERS:" + rule.Id, rule.Defeaters.Count, MaxRuleDefeaters); } foreach (LogicTheory theory in Store.Theories) AuditBound(rows, "THEORY_QUESTIONS:" + theory.Id, theory.Questions.Count, MaxTheoryQuestions); foreach (LogicDecisionModel decision in Store.Decisions) { AuditBound(rows, "DECISION_CRITERIA:" + decision.Id, decision.Criteria.Count, MaxDecisionCriteria); AuditBound(rows, "DECISION_ALTERNATIVES:" + decision.Id, decision.Alternatives.Count, MaxDecisionAlternatives); } string ledger = VerifyLedger(ReadLedger(ctx, 8192)); if (!ledger.StartsWith("CHAIN VERIFIED", StringComparison.OrdinalIgnoreCase) && ledger != "EMPTY LEDGER") Audit(rows, "FAIL", "LEDGER_INTEGRITY", "ledger", ledger, null); else Audit(rows, "INFO", "LEDGER_STATUS", "ledger", ledger, null); if (rows.Count == 1 && rows[0].Code == "LEDGER_STATUS") Audit(rows, "INFO", "STRUCTURE_CLEAN", "store", "No structural findings in the bounded audit", null); return rows;
        }

        private static void Audit(List<LogicAuditFinding> rows, string severity, string code, string subject, string detail, string nodeId) { rows.Add(new LogicAuditFinding { Severity = severity, Code = code, SubjectId = subject, Detail = detail, NodeId = nodeId }); }
        private static void AuditBound(List<LogicAuditFinding> rows, string name, int count, int bound) { if (count > bound) Audit(rows, "FAIL", "BOUND_EXCEEDED", name, count.ToString(CultureInfo.InvariantCulture) + " > " + bound.ToString(CultureInfo.InvariantCulture), null); }

        private static void OpenLedger(Window owner, DeepSystemsContext ctx)
        {
            List<LogicLedgerRecord> records = ReadLedger(ctx, 8192); string verification = VerifyLedger(records); Window w = W(owner, "YOMI · LOGIC LEDGER", 1180, 780); DockPanel root = Shell("APPEND-ONLY EPISTEMIC LEDGER", verification + " · every mutation binds sequence, prior hash, commit correlation and optional kernel fingerprint"); WrapPanel tools = new WrapPanel { Margin = new Thickness(0, 6, 0, 8) }; tools.Children.Add(Btn("VERIFY CHAIN", delegate { MessageBox.Show(w, VerifyLedger(ReadLedger(ctx, 8192)), "YOMI · Logic Ledger"); })); tools.Children.Add(Btn("HADAL DESCENT", delegate { AbyssalKnowledgeEngine.DescendFromExternal(w, ctx, "Logic Ledger", records, LedgerPath(ctx), "$ledger", "LOGIC FOUNDRY › LEDGER"); })); DockPanel.SetDock(tools, Dock.Top); root.Children.Add(tools); ListBox list = List(); list.ItemsSource = records.OrderByDescending(r => r.Sequence).ToList(); list.MouseDoubleClick += delegate { LogicLedgerRecord row = list.SelectedItem as LogicLedgerRecord; if (row != null) MessageBox.Show(w, Json.Serialize(row), "YOMI · Ledger Record " + row.Sequence); }; root.Children.Add(list); w.Content = root; w.Show();
        }

        private static void Load(DeepSystemsContext ctx)
        {
            lock (Gate)
            {
                if (Store != null && String.Equals(LoadedRoot, ctx.DataRoot, StringComparison.OrdinalIgnoreCase)) return; LoadedRoot = ctx.DataRoot; Store = new LogicFoundryStore(); string path = StorePath(ctx); try { if (File.Exists(path)) { LogicFoundryStore loaded = Json.Deserialize<LogicFoundryStore>(File.ReadAllText(path, Encoding.UTF8)); if (loaded == null || loaded.Schema > 1) throw new InvalidDataException("Unsupported Logic Foundry schema."); Store = loaded; } } catch { PreserveCorrupt(path); Store = LoadPreviousStore(path) ?? new LogicFoundryStore(); } NormalizeStore();
            }
        }

        private static LogicFoundryStore LoadPreviousStore(string path)
        {
            try { string previous = path + ".previous"; if (!File.Exists(previous)) return null; LogicFoundryStore loaded = Json.Deserialize<LogicFoundryStore>(File.ReadAllText(previous, Encoding.UTF8)); return loaded != null && loaded.Schema <= 1 ? loaded : null; } catch { return null; }
        }

        private static void NormalizeStore()
        {
            if (Store == null) Store = new LogicFoundryStore(); Store.Schema = 1; if (Store.Worlds == null) Store.Worlds = new List<LogicWorld>(); if (Store.Facts == null) Store.Facts = new List<LogicFact>(); if (Store.Rules == null) Store.Rules = new List<LogicRule>(); if (Store.Theories == null) Store.Theories = new List<LogicTheory>(); if (Store.Hypotheses == null) Store.Hypotheses = new List<LogicHypothesis>(); if (Store.SavedProofs == null) Store.SavedProofs = new List<LogicSavedProof>(); if (Store.Decisions == null) Store.Decisions = new List<LogicDecisionModel>(); if (Store.QueryHistory == null) Store.QueryHistory = new List<string>();
            if (!Store.Worlds.Any(w => String.Equals(w.Kind, "ACTUAL", StringComparison.OrdinalIgnoreCase) && String.IsNullOrWhiteSpace(w.ParentWorldId))) Store.Worlds.Insert(0, new LogicWorld { Id = "world-actual", Name = "Actual World", Kind = "ACTUAL", Status = "ACTIVE", CreatedUtc = Now(), UpdatedUtc = Now(), Charter = "Root world for operator assertions and inherited evidence." });
            HashSet<string> worldIds = new HashSet<string>(Store.Worlds.Where(w => !String.IsNullOrWhiteSpace(w.Id)).Select(w => w.Id), StringComparer.OrdinalIgnoreCase); foreach (LogicWorld w in Store.Worlds) { if (String.IsNullOrWhiteSpace(w.Id)) w.Id = Id("world"); if (w.ExcludedFactIds == null) w.ExcludedFactIds = new List<string>(); if (String.IsNullOrWhiteSpace(w.Status)) w.Status = "ACTIVE"; if (String.IsNullOrWhiteSpace(w.Kind)) w.Kind = String.IsNullOrWhiteSpace(w.ParentWorldId) ? "ACTUAL" : "HYPOTHETICAL"; if (!String.IsNullOrWhiteSpace(w.ParentWorldId) && (!worldIds.Contains(w.ParentWorldId) || String.Equals(w.ParentWorldId, w.Id, StringComparison.OrdinalIgnoreCase))) w.ParentWorldId = ActualWorldId(Store.Worlds); }
            string actualId = ActualWorldId(Store.Worlds); foreach (LogicFact f in Store.Facts) { if (String.IsNullOrWhiteSpace(f.Id)) f.Id = Id("fact"); if (String.IsNullOrWhiteSpace(f.WorldId) || !Store.Worlds.Any(w => String.Equals(w.Id, f.WorldId, StringComparison.OrdinalIgnoreCase))) f.WorldId = actualId; if (f.EvidenceNodeIds == null) f.EvidenceNodeIds = new List<string>(); if (String.IsNullOrWhiteSpace(f.Status)) f.Status = "ACTIVE"; if (String.IsNullOrWhiteSpace(f.EpistemicClass)) f.EpistemicClass = "OPERATOR_ASSERTION"; f.Weight = Clamp01(f.Weight <= 0 ? 1 : f.Weight); f.Literal = LogicLiteral.Parse(f.Literal).Display; }
            foreach (LogicRule r in Store.Rules) { if (String.IsNullOrWhiteSpace(r.Id)) r.Id = Id("rule"); if (String.IsNullOrWhiteSpace(r.WorldId)) r.WorldId = actualId; if (r.Premises == null) r.Premises = new List<string>(); if (r.Defeaters == null) r.Defeaters = new List<string>(); if (r.EvidenceNodeIds == null) r.EvidenceNodeIds = new List<string>(); if (String.IsNullOrWhiteSpace(r.Status)) r.Status = "ACTIVE"; if (String.IsNullOrWhiteSpace(r.Kind)) r.Kind = "DEDUCTIVE"; }
            foreach (LogicTheory t in Store.Theories) { if (t.FactIds == null) t.FactIds = new List<string>(); if (t.RuleIds == null) t.RuleIds = new List<string>(); if (t.Questions == null) t.Questions = new List<string>(); if (String.IsNullOrWhiteSpace(t.Status)) t.Status = "ACTIVE"; }
            foreach (LogicHypothesis h in Store.Hypotheses) { if (h.Assumptions == null) h.Assumptions = new List<string>(); if (h.Falsifiers == null) h.Falsifiers = new List<string>(); if (h.EvidenceNodeIds == null) h.EvidenceNodeIds = new List<string>(); if (h.Notes == null) h.Notes = new List<string>(); if (String.IsNullOrWhiteSpace(h.Status)) h.Status = "OPEN"; }
            foreach (LogicSavedProof p in Store.SavedProofs) if (p.EvidenceNodeIds == null) p.EvidenceNodeIds = new List<string>(); foreach (LogicDecisionModel d in Store.Decisions) { if (d.Criteria == null) d.Criteria = new List<LogicDecisionCriterion>(); if (d.Alternatives == null) d.Alternatives = new List<LogicDecisionAlternative>(); if (d.EvidenceNodeIds == null) d.EvidenceNodeIds = new List<string>(); foreach (LogicDecisionAlternative a in d.Alternatives) if (a.Scores == null) a.Scores = new Dictionary<string, double>(StringComparer.OrdinalIgnoreCase); } TrimStore();
        }

        private static void TrimStore()
        {
            Store.Worlds = Store.Worlds.OrderBy(w => String.Equals(w.Kind, "ACTUAL", StringComparison.OrdinalIgnoreCase) ? 0 : 1).ThenByDescending(w => w.UpdatedUtc ?? w.CreatedUtc).Take(MaxWorlds).ToList(); Store.Facts = Store.Facts.OrderByDescending(f => f.UpdatedUtc ?? f.CreatedUtc).Take(MaxFacts).ToList(); Store.Rules = Store.Rules.OrderByDescending(r => r.UpdatedUtc ?? r.CreatedUtc).Take(MaxRules).ToList(); Store.Theories = Store.Theories.OrderByDescending(t => t.UpdatedUtc ?? t.CreatedUtc).Take(MaxTheories).ToList(); Store.Hypotheses = Store.Hypotheses.OrderByDescending(h => h.UpdatedUtc ?? h.CreatedUtc).Take(MaxHypotheses).ToList(); Store.SavedProofs = Store.SavedProofs.OrderByDescending(p => p.CreatedUtc).Take(MaxSavedProofs).ToList(); Store.Decisions = Store.Decisions.OrderByDescending(d => d.UpdatedUtc ?? d.CreatedUtc).Take(MaxDecisions).ToList(); Store.QueryHistory = Store.QueryHistory.Where(q => !String.IsNullOrWhiteSpace(q)).Distinct(StringComparer.OrdinalIgnoreCase).Take(MaxQueryHistory).ToList(); foreach (LogicWorld w in Store.Worlds) w.ExcludedFactIds = w.ExcludedFactIds.Distinct(StringComparer.OrdinalIgnoreCase).Take(MaxFacts).ToList(); foreach (LogicFact f in Store.Facts) f.EvidenceNodeIds = f.EvidenceNodeIds.Distinct(StringComparer.OrdinalIgnoreCase).Take(MaxEvidenceAnchors).ToList(); foreach (LogicRule r in Store.Rules) { r.Premises = r.Premises.Take(MaxRulePremises).ToList(); r.Defeaters = r.Defeaters.Take(MaxRuleDefeaters).ToList(); r.EvidenceNodeIds = r.EvidenceNodeIds.Distinct(StringComparer.OrdinalIgnoreCase).Take(MaxEvidenceAnchors).ToList(); } foreach (LogicTheory t in Store.Theories) { t.FactIds = t.FactIds.Distinct(StringComparer.OrdinalIgnoreCase).Take(MaxFacts).ToList(); t.RuleIds = t.RuleIds.Distinct(StringComparer.OrdinalIgnoreCase).Take(MaxRules).ToList(); t.Questions = t.Questions.Distinct(StringComparer.OrdinalIgnoreCase).Take(MaxTheoryQuestions).ToList(); } foreach (LogicHypothesis h in Store.Hypotheses) { h.Assumptions = h.Assumptions.Take(MaxHypothesisTerms).ToList(); h.Falsifiers = h.Falsifiers.Take(MaxHypothesisTerms * 2).ToList(); h.Notes = h.Notes.Take(MaxHypothesisNotes).ToList(); h.EvidenceNodeIds = h.EvidenceNodeIds.Distinct(StringComparer.OrdinalIgnoreCase).Take(MaxEvidenceAnchors).ToList(); } foreach (LogicSavedProof p in Store.SavedProofs) p.EvidenceNodeIds = p.EvidenceNodeIds.Distinct(StringComparer.OrdinalIgnoreCase).Take(MaxEvidenceAnchors * 2).ToList(); foreach (LogicDecisionModel d in Store.Decisions) { d.Criteria = d.Criteria.Take(MaxDecisionCriteria).ToList(); d.Alternatives = d.Alternatives.Take(MaxDecisionAlternatives).ToList(); d.EvidenceNodeIds = d.EvidenceNodeIds.Distinct(StringComparer.OrdinalIgnoreCase).Take(MaxEvidenceAnchors).ToList(); }
        }

        private static void Save(DeepSystemsContext ctx)
        {
            lock (Gate) { NormalizeStore(); Store.Revision = Math.Max(0, Store.Revision) + 1; Store.UpdatedUtc = Now(); Store.LastCommitId = Id("logic-commit"); string path = StorePath(ctx); Directory.CreateDirectory(Path.GetDirectoryName(path)); AtomicWrite(path, Json.Serialize(Store)); }
        }

        private static void AtomicWrite(string path, string text)
        {
            string temp = path + ".tmp." + Guid.NewGuid().ToString("N"); File.WriteAllText(temp, text ?? "", new UTF8Encoding(false)); if (File.Exists(path)) { string previous = path + ".previous"; try { File.Replace(temp, path, previous, true); return; } catch { try { File.Copy(path, previous, true); } catch { } } } if (File.Exists(path)) File.Delete(path); File.Move(temp, path);
        }

        private static void PreserveCorrupt(string path)
        {
            try { if (!File.Exists(path)) return; byte[] bytes = File.ReadAllBytes(path); string destination = path + ".corrupt." + HashBytes(bytes).Substring(0, 16) + ".json"; if (!File.Exists(destination)) File.Copy(path, destination); } catch { }
        }

        private static void AppendLedger(DeepSystemsContext ctx, string evt, string subject, string detail, string kernelFingerprint)
        {
            lock (Gate) try { Directory.CreateDirectory(ctx.StateRoot); List<LogicLedgerRecord> prior = ReadLedger(ctx, 8192); LogicLedgerRecord last = prior.OrderByDescending(r => r.Sequence).FirstOrDefault(); LogicLedgerRecord row = new LogicLedgerRecord { Schema = 1, Sequence = last == null ? 1 : last.Sequence + 1, Utc = Now(), Event = Short(evt, 120), Subject = Short(subject, 512), Detail = Short(detail, MaxLongText), CorrelationId = Store == null ? "" : Store.LastCommitId, KernelFingerprint = Short(kernelFingerprint, 128), PrevHash = last == null ? new string('0', 64) : last.EntryHash }; row.EntryHash = LedgerHash(row); byte[] bytes = Encoding.UTF8.GetBytes(Json.Serialize(row) + Environment.NewLine); using (FileStream stream = new FileStream(LedgerPath(ctx), FileMode.Append, FileAccess.Write, FileShare.Read, 4096, FileOptions.WriteThrough)) { stream.Write(bytes, 0, bytes.Length); stream.Flush(); } } catch { }
        }

        private static List<LogicLedgerRecord> ReadLedger(DeepSystemsContext ctx, int cap)
        {
            List<LogicLedgerRecord> rows = new List<LogicLedgerRecord>(); string path = LedgerPath(ctx); if (!File.Exists(path)) return rows; try { foreach (string line in TakeLastLocal(File.ReadLines(path).Where(x => !String.IsNullOrWhiteSpace(x)), cap)) try { LogicLedgerRecord row = Json.Deserialize<LogicLedgerRecord>(line); if (row != null) rows.Add(row); } catch { } } catch { } return rows;
        }

        private static string VerifyLedger(List<LogicLedgerRecord> rows)
        {
            if (rows == null || rows.Count == 0) return "EMPTY LEDGER"; rows = rows.OrderBy(r => r.Sequence).ToList(); string previous = rows[0].PrevHash; long expected = rows[0].Sequence; foreach (LogicLedgerRecord row in rows) { if (row.Sequence != expected) return "CHAIN GAP @ " + expected.ToString(CultureInfo.InvariantCulture); if (!String.Equals(row.PrevHash ?? "", previous ?? "", StringComparison.OrdinalIgnoreCase)) return "PREV HASH MISMATCH @ " + row.Sequence.ToString(CultureInfo.InvariantCulture); if (!String.Equals(row.EntryHash ?? "", LedgerHash(row), StringComparison.OrdinalIgnoreCase)) return "ENTRY HASH MISMATCH @ " + row.Sequence.ToString(CultureInfo.InvariantCulture); previous = row.EntryHash; expected++; } return "CHAIN VERIFIED · " + rows.Count.ToString(CultureInfo.InvariantCulture) + " RECORDS";
        }

        private static string LedgerHash(LogicLedgerRecord r) { return HashText(r.Schema + "|" + r.Sequence + "|" + (r.Utc ?? "") + "|" + (r.Event ?? "") + "|" + (r.Subject ?? "") + "|" + (r.Detail ?? "") + "|" + (r.CorrelationId ?? "") + "|" + (r.KernelFingerprint ?? "") + "|" + (r.PrevHash ?? "")); }
        private static string StorePath(DeepSystemsContext ctx) { return Path.Combine(ctx.StateRoot, "controller-epistemic-logic.json"); }
        private static string LedgerPath(DeepSystemsContext ctx) { return Path.Combine(ctx.StateRoot, "controller-epistemic-logic-ledger.jsonl"); }

        private static LogicWorld World(string id) { return Store.Worlds.FirstOrDefault(w => String.Equals(w.Id, id, StringComparison.OrdinalIgnoreCase)); }
        private static string ActualWorldId(IEnumerable<LogicWorld> worlds) { LogicWorld actual = (worlds ?? Enumerable.Empty<LogicWorld>()).FirstOrDefault(w => String.Equals(w.Kind, "ACTUAL", StringComparison.OrdinalIgnoreCase) && String.IsNullOrWhiteSpace(w.ParentWorldId)); return actual == null ? "world-actual" : actual.Id; }
        private static List<LogicWorld> WorldAncestry(LogicWorld world) { List<LogicWorld> rows = new List<LogicWorld>(); HashSet<string> seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase); LogicWorld cursor = world; while (cursor != null && rows.Count < 64 && seen.Add(cursor.Id ?? "")) { rows.Add(cursor); cursor = World(cursor.ParentWorldId); } return rows; }
        private static bool HasWorldCycle(LogicWorld world) { HashSet<string> seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase); LogicWorld cursor = world; for (int depth = 0; cursor != null && depth < 65; depth++) { if (!seen.Add(cursor.Id ?? "")) return true; cursor = World(cursor.ParentWorldId); } return false; }
        private static int WorldDepth(LogicWorld world) { return Math.Max(0, WorldAncestry(world).Count - 1); }
        private static List<LogicFact> VisibleFacts(LogicWorld world) { List<LogicWorld> ancestry = WorldAncestry(world); HashSet<string> ids = new HashSet<string>(ancestry.Select(w => w.Id), StringComparer.OrdinalIgnoreCase); HashSet<string> excluded = new HashSet<string>(ancestry.SelectMany(w => w.ExcludedFactIds ?? new List<string>()), StringComparer.OrdinalIgnoreCase); return Store.Facts.Where(f => ids.Contains(f.WorldId) && !excluded.Contains(f.Id)).ToList(); }
        private static List<LogicRule> VisibleRules(LogicWorld world) { HashSet<string> ids = new HashSet<string>(WorldAncestry(world).Select(w => w.Id), StringComparer.OrdinalIgnoreCase); return Store.Rules.Where(r => ids.Contains(r.WorldId)).ToList(); }
        private static LogicWorld ChooseWorld(Window owner, string preferredId) { return ChooseObject(owner, "SELECT MODAL WORLD", "Select evaluation context", Store.Worlds.Where(q => Active(q.Status)).OrderBy(q => WorldDepth(q)).ThenBy(q => q.Name).Cast<object>().ToList(), preferredId) as LogicWorld; }

        private static string DescribeWorldNode(WorldNode node)
        {
            StringBuilder s = new StringBuilder(); s.AppendLine("WORLD OBJECT ID    " + node.Id); s.AppendLine("KIND               " + node.Kind); s.AppendLine("LABEL              " + node.Label); s.AppendLine("EVIDENCE CLASS     " + node.EvidenceClass); s.AppendLine("SOURCE             " + node.SourcePath); s.AppendLine("JSON PATH          " + node.JsonPath); s.AppendLine("FINGERPRINT        " + node.Fingerprint); s.AppendLine("MODIFIED UTC       " + node.ModifiedUtc.ToString("o", CultureInfo.InvariantCulture)); s.AppendLine(); s.AppendLine("SUMMARY"); s.AppendLine(node.Summary ?? "∅"); s.AppendLine(); s.AppendLine("IDENTITIES"); foreach (string token in node.IdentityTokens) s.AppendLine("  " + token); s.AppendLine(); s.AppendLine("PROPERTIES"); foreach (KeyValuePair<string, string> property in node.Properties.OrderBy(x => x.Key)) s.AppendLine("  " + property.Key + " = " + property.Value); return s.ToString();
        }

        private static List<string> SplitStatements(string raw) { return (raw ?? "").Replace("\r", "").Split(new[] { '\n', ';' }, StringSplitOptions.RemoveEmptyEntries).Select(x => x.Trim()).Where(x => !String.IsNullOrWhiteSpace(x)).Take(512).ToList(); }
        private static IEnumerable<string> Variables(LogicLiteral literal) { return literal == null ? Enumerable.Empty<string>() : literal.Arguments.Where(LogicLiteral.IsVariable).Distinct(StringComparer.OrdinalIgnoreCase); }
        private static string Opposite(string raw) { LogicLiteral literal = LogicLiteral.Parse(raw); literal.Negated = !literal.Negated; return literal.Display; }
        private static int TruthOrder(string truth) { if (truth == "BOTH") return 0; if (truth == "TRUE_ONLY") return 1; if (truth == "FALSE_ONLY") return 2; return 3; }
        private static double Clamp01(double value) { return Math.Max(0, Math.Min(1, value)); }
        private static string Short(string value, int cap) { value = value ?? ""; cap = Math.Max(1, cap); return value.Length <= cap ? value : value.Substring(0, cap - 1) + "…"; }
        private static string HashRule(LogicRule rule) { return HashText((rule.Id ?? "") + "|" + (rule.Kind ?? "") + "|" + rule.Priority + "|" + String.Join("&", rule.Premises.ToArray()) + "|" + (rule.Consequent ?? "") + "|" + String.Join("&", rule.Defeaters.ToArray())); }
        private static string HashText(string value) { return HashBytes(Encoding.UTF8.GetBytes(value ?? "")); }
        private static string HashBytes(byte[] value) { using (SHA256 hash = SHA256.Create()) return BitConverter.ToString(hash.ComputeHash(value ?? new byte[0])).Replace("-", "").ToLowerInvariant(); }
        private static string Id(string prefix) { return prefix + "-" + DateTime.UtcNow.ToString("yyyyMMddHHmmssfff", CultureInfo.InvariantCulture) + "-" + Guid.NewGuid().ToString("N").Substring(0, 8); }
        private static string Now() { return DateTime.UtcNow.ToString("o", CultureInfo.InvariantCulture); }
        private static IEnumerable<T> TakeLastLocal<T>(IEnumerable<T> source, int count) { if (source == null) yield break; Queue<T> queue = new Queue<T>(); foreach (T item in source) { queue.Enqueue(item); if (queue.Count > count) queue.Dequeue(); } foreach (T item in queue) yield return item; }

        private static Window W(Window owner, string title, double width, double height) { return new Window { Title = title, Width = width, Height = height, MinWidth = Math.Min(width, 820), MinHeight = Math.Min(height, 560), Background = Bg, Foreground = Text, WindowStartupLocation = WindowStartupLocation.CenterOwner, Owner = owner, FontFamily = new FontFamily("Segoe UI") }; }
        private static DockPanel Shell(string title, string subtitle) { DockPanel root = new DockPanel { Margin = new Thickness(16) }; StackPanel head = new StackPanel { Margin = new Thickness(0, 0, 0, 10) }; head.Children.Add(T(title, 24, Text, FontWeights.Bold)); head.Children.Add(T(subtitle, 12, Muted, FontWeights.Normal)); DockPanel.SetDock(head, Dock.Top); root.Children.Add(head); return root; }
        private static TextBlock T(string value, double size, Brush foreground, FontWeight weight) { return new TextBlock { Text = value ?? "", FontSize = size, Foreground = foreground, FontWeight = weight, TextWrapping = TextWrapping.Wrap, Margin = new Thickness(0, 2, 0, 2) }; }
        private static Button Btn(string label, RoutedEventHandler click) { Button button = new Button { Content = label, Margin = new Thickness(0, 0, 8, 8), Padding = new Thickness(12, 7, 12, 7), Background = Raised, Foreground = Text, BorderBrush = Border, BorderThickness = new Thickness(1), MinWidth = 112 }; if (click != null) button.Click += click; return button; }
        private static ListBox List() { return new ListBox { Background = Surface, Foreground = Text, BorderBrush = Border, BorderThickness = new Thickness(1), Margin = new Thickness(0, 6, 0, 0), Padding = new Thickness(5), FontFamily = new FontFamily("Cascadia Mono, Consolas") }; }
        private static TextBox ReadOnly(string value) { return new TextBox { Text = value ?? "", IsReadOnly = true, AcceptsReturn = true, TextWrapping = TextWrapping.Wrap, VerticalScrollBarVisibility = ScrollBarVisibility.Auto, Background = Surface, Foreground = Text, BorderBrush = Border, BorderThickness = new Thickness(1), Padding = new Thickness(10), Margin = new Thickness(0, 6, 6, 0), FontFamily = new FontFamily("Cascadia Mono, Consolas") }; }
        private static void Portal(Panel parent, string badge, string title, string description, Action open) { Button button = new Button { Width = 350, Height = 116, Margin = new Thickness(0, 0, 10, 10), Padding = new Thickness(12), Background = Surface, Foreground = Text, BorderBrush = Border, BorderThickness = new Thickness(1), HorizontalContentAlignment = HorizontalAlignment.Stretch }; StackPanel content = new StackPanel(); content.Children.Add(T(badge + "   " + title, 14, Accent, FontWeights.Bold)); content.Children.Add(T(description, 11.5, Muted, FontWeights.Normal)); button.Content = content; button.Click += delegate { if (open != null) open(); }; parent.Children.Add(button); }
        private static Brush B(string hex) { return new SolidColorBrush((Color)ColorConverter.ConvertFromString(hex)); }

        private static string Prompt(Window owner, string title, string label, string initial)
        {
            Window w = W(owner, "YOMI · " + title, 640, 270); DockPanel root = new DockPanel { Margin = new Thickness(16) }; TextBlock caption = T(label, 12, Muted, FontWeights.Normal); DockPanel.SetDock(caption, Dock.Top); root.Children.Add(caption); TextBox editor = new TextBox { Text = initial ?? "", MaxLength = MaxShortText, Margin = new Thickness(0, 8, 0, 10), Background = Surface, Foreground = Text, BorderBrush = Border, Padding = new Thickness(8) }; DockPanel.SetDock(editor, Dock.Top); root.Children.Add(editor); WrapPanel buttons = new WrapPanel { HorizontalAlignment = HorizontalAlignment.Right }; string result = null; buttons.Children.Add(Btn("OK", delegate { result = editor.Text; w.DialogResult = true; })); buttons.Children.Add(Btn("CANCEL", delegate { w.DialogResult = false; })); root.Children.Add(buttons); w.Content = root; bool? accepted = w.ShowDialog(); return accepted == true ? result : null;
        }

        private static string PromptLarge(Window owner, string title, string label, string initial)
        {
            Window w = W(owner, "YOMI · " + title, 760, 500); DockPanel root = new DockPanel { Margin = new Thickness(16) }; TextBlock caption = T(label, 12, Muted, FontWeights.Normal); DockPanel.SetDock(caption, Dock.Top); root.Children.Add(caption); TextBox editor = new TextBox { Text = initial ?? "", MaxLength = MaxLongText, AcceptsReturn = true, AcceptsTab = true, TextWrapping = TextWrapping.Wrap, VerticalScrollBarVisibility = ScrollBarVisibility.Auto, Margin = new Thickness(0, 8, 0, 0), Background = Surface, Foreground = Text, BorderBrush = Border, Padding = new Thickness(10), FontFamily = new FontFamily("Cascadia Mono, Consolas") }; WrapPanel buttons = new WrapPanel { HorizontalAlignment = HorizontalAlignment.Right, Margin = new Thickness(0, 10, 0, 0) }; string result = null; buttons.Children.Add(Btn("SAVE", delegate { result = editor.Text; w.DialogResult = true; })); buttons.Children.Add(Btn("CANCEL", delegate { w.DialogResult = false; })); DockPanel.SetDock(buttons, Dock.Bottom); root.Children.Add(buttons); root.Children.Add(editor); w.Content = root; bool? accepted = w.ShowDialog(); return accepted == true ? result : null;
        }

        private static string Choose(Window owner, string title, string label, IEnumerable<string> choices, string preferred)
        {
            object selected = ChooseObject(owner, title, label, (choices ?? Enumerable.Empty<string>()).Cast<object>().ToList(), preferred); return selected == null ? null : Convert.ToString(selected, CultureInfo.InvariantCulture);
        }

        private static object ChooseObject(Window owner, string title, string label, IList<object> choices) { return ChooseObject(owner, title, label, choices, null); }
        private static object ChooseObject(Window owner, string title, string label, IList<object> choices, string preferredId)
        {
            Window w = W(owner, "YOMI · " + title, 700, 460); DockPanel root = new DockPanel { Margin = new Thickness(16) }; TextBlock caption = T(label, 12, Muted, FontWeights.Normal); DockPanel.SetDock(caption, Dock.Top); root.Children.Add(caption); ListBox list = List(); list.ItemsSource = choices ?? new List<object>(); if (!String.IsNullOrWhiteSpace(preferredId)) { LogicWorld preferred = list.Items.Cast<object>().OfType<LogicWorld>().FirstOrDefault(x => String.Equals(x.Id, preferredId, StringComparison.OrdinalIgnoreCase)); if (preferred != null) list.SelectedItem = preferred; } if (list.SelectedIndex < 0 && list.Items.Count > 0) list.SelectedIndex = 0; WrapPanel buttons = new WrapPanel { HorizontalAlignment = HorizontalAlignment.Right, Margin = new Thickness(0, 10, 0, 0) }; object result = null; buttons.Children.Add(Btn("SELECT", delegate { result = list.SelectedItem; w.DialogResult = true; })); buttons.Children.Add(Btn("CANCEL", delegate { w.DialogResult = false; })); list.MouseDoubleClick += delegate { result = list.SelectedItem; if (result != null) w.DialogResult = true; }; DockPanel.SetDock(buttons, Dock.Bottom); root.Children.Add(buttons); root.Children.Add(list); w.Content = root; bool? accepted = w.ShowDialog(); return accepted == true ? result : null;
        }

        private sealed class LogicWorldGenealogyRow { public int Depth; public LogicWorld World; public override string ToString() { return new string(' ', Math.Max(0, Math.Min(32, Depth)) * 2) + (Depth == 0 ? "◇ " : "└ ") + (World == null ? "∅" : World.Name) + "   ·   " + (World == null ? "" : World.Kind); } }
        private sealed class LogicSemanticRow { public string Atom; public string Truth; public int PositiveDerivations; public int NegativeDerivations; public override string ToString() { return (Truth ?? "NEITHER").PadRight(11) + "   ·   +" + PositiveDerivations.ToString(CultureInfo.InvariantCulture) + " / -" + NegativeDerivations.ToString(CultureInfo.InvariantCulture) + "   ·   " + (Atom ?? "∅"); } }
        private sealed class LogicFalsifierRow { public string Literal; public string Truth; public int Priority; public override string ToString() { return (Truth ?? "NEITHER").PadRight(11) + "   ·   " + (Literal ?? "∅") + (Truth == "TRUE_ONLY" || Truth == "BOTH" ? "   ·   ACTIVE ATTACK" : ""); } }
        private sealed class LogicTheoryQuestionRow { public string Query; public string Truth; public int Evidence; public override string ToString() { return (Truth ?? "NEITHER").PadRight(11) + "   ·   evidence " + Evidence.ToString(CultureInfo.InvariantCulture).PadLeft(3) + "   ·   " + (Query ?? "∅"); } }
        private sealed class LogicDecisionResultRow { public int Rank; public string Alternative; public double Utility; public bool Pareto; public double MaxRegret; public double Robustness; public override string ToString() { return "#" + Rank.ToString(CultureInfo.InvariantCulture).PadRight(3) + "   " + (Pareto ? "PARETO" : "      ") + "   ·   utility " + Utility.ToString("0.000", CultureInfo.InvariantCulture) + "   ·   regret " + MaxRegret.ToString("0.000", CultureInfo.InvariantCulture) + "   ·   robustness " + Robustness.ToString("P0", CultureInfo.InvariantCulture) + "   ·   " + (Alternative ?? "∅"); } }
        private sealed class LogicModalTruthRow { public LogicWorld World; public string Truth; public string KernelFingerprint; public int Contradictions; public override string ToString() { return (Truth ?? "NEITHER").PadRight(11) + "   ·   contradictions " + Contradictions.ToString(CultureInfo.InvariantCulture).PadLeft(4) + "   ·   depth " + (World == null ? "0" : WorldDepth(World).ToString(CultureInfo.InvariantCulture)) + "   ·   " + (World == null ? "∅" : World.Name) + "   ·   " + Short(KernelFingerprint, 12); } }
        private sealed class LogicRuleComponentRow { public List<string> Predicates = new List<string>(); public List<LogicRule> Rules = new List<LogicRule>(); public bool Recursive; public int InternalEdges; public override string ToString() { return (Recursive ? "RECURSIVE" : "ACYCLIC ") + "   ·   " + Predicates.Count.ToString(CultureInfo.InvariantCulture) + " predicates · " + InternalEdges.ToString(CultureInfo.InvariantCulture) + " internal edges · " + Rules.Count.ToString(CultureInfo.InvariantCulture) + " rules · " + String.Join(", ", Predicates.Take(8).ToArray()); } }
        private sealed class LogicAuditFinding { public string Severity; public string Code; public string SubjectId; public string Detail; public string NodeId; public override string ToString() { return (Severity ?? "INFO").PadRight(5) + "   ·   " + (Code ?? "AUDIT").PadRight(30) + "   ·   " + (SubjectId ?? "∅") + "   ·   " + (Detail ?? ""); } }
    }
